/** Separador de sección con título e ícono (estilo institucional INTT). */
function SectionDivider({ icon, title }: { icon: React.ReactNode; title: string }) {
  return (
    <div className="flex items-center gap-3 pt-4">
      <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-[var(--intt-navy-deep)] text-white">
        {icon}
      </div>
      <h3 className="text-lg font-bold text-[var(--intt-navy-deep)]">{title}</h3>
      <div className="intt-gold-rule h-0.5 flex-1 rounded-full opacity-40" />
    </div>
  );
}

/** Mini gráfico de dona para indicadores sí/no/más o menos. */
function MiniDonut({ data }: { data: { label: string; count: number }[] }) {
  const total = data.reduce((s, d) => s + d.count, 0) || 1;
  return (
    <div className="flex items-center gap-4 py-2">
      <div className="relative h-24 w-24 shrink-0">
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie
              data={data}
              dataKey="count"
              nameKey="label"
              cx="50%"
              cy="50%"
              innerRadius={32}
              outerRadius={48}
              paddingAngle={2}
            >
              {data.map((_, i) => (
                <Cell key={i} fill={COLORS[i % COLORS.length]} />
              ))}
            </Pie>
            <Tooltip />
          </PieChart>
        </ResponsiveContainer>
        <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center">
          <span className="text-lg font-bold text-[var(--intt-navy-deep)]">{total}</span>
          <span className="text-[9px] text-muted-foreground">total</span>
        </div>
      </div>
      <div className="flex-1 space-y-1">
        {data.map((d, i) => (
          <div key={d.label} className="flex items-center gap-2 text-xs">
            <span
              className="h-2.5 w-2.5 shrink-0 rounded-sm"
              style={{ backgroundColor: COLORS[i % COLORS.length] }}
            />
            <span className="flex-1 truncate text-muted-foreground">{d.label}</span>
            <span className="font-mono font-medium">{d.count}</span>
            <span className="w-8 text-right text-[10px] text-muted-foreground">
              {Math.round((d.count / total) * 100)}%
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

function KpiCard({
  icon,
  label,
  value,
  sub,
  color,
}: {
  icon: React.ReactNode;
  label: string;
  value: string | number;
  sub?: string;
  color: string;
}) {
  return (
    <Card>
      <CardContent className="p-5">
        <div className={`mb-3 flex h-10 w-10 items-center justify-center rounded-lg ${color}`}>
          {icon}
        </div>
        <p className="text-sm text-muted-foreground">{label}</p>
        <p className="mt-1 text-2xl font-bold">{value}</p>
        {sub && <p className="mt-0.5 text-xs text-muted-foreground">{sub}</p>}
      </CardContent>
    </Card>
  );
}

function ChartCard({
  title,
  description,
  icon,
  children,
}: {
  title: string;
  description?: string;
  icon?: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <Card>
      <CardHeader className="pb-2">
        <div className="flex items-center gap-2">
          {icon && <span className="text-primary">{icon}</span>}
          <div>
            <CardTitle className="text-base">{title}</CardTitle>
            {description && (
              <CardDescription className="text-xs">{description}</CardDescription>
            )}
          </div>
        </div>
      </CardHeader>
      <CardContent>{children}</CardContent>
    </Card>
  );
}

function ScaleCard({
  title,
  avg,
  data,
  color,
  labels,
}: {
  title: string;
  avg: number;
  data: Record<string, number>;
  color: string;
  labels: [string, string] | string[];
}) {
  const chartData = Object.entries(data).map(([k, v]) => ({ name: k, value: v }));
  const pctVal = (avg / 5) * 100;
  return (
    <Card>
      <CardHeader className="pb-2">
        <CardTitle className="text-base">{title}</CardTitle>
        <CardDescription className="text-xs">
          Promedio: <strong className="text-foreground">{avg.toFixed(2)} / 5</strong>
        </CardDescription>
      </CardHeader>
      <CardContent>
        <div className="flex items-center gap-4">
          <div className="relative h-32 w-32 shrink-0">
            <ResponsiveContainer width="100%" height="100%">
              <RadialBarChart
                innerRadius="70%"
                outerRadius="100%"
                data={[{ name: title, value: pctVal, fill: color }]}
                startAngle={90}
                endAngle={90 - 360}
              >
                <RadialBar background dataKey="value" cornerRadius={10} />
              </RadialBarChart>
            </ResponsiveContainer>
            <div className="absolute inset-0 flex flex-col items-center justify-center">
              <span className="text-2xl font-bold">{avg.toFixed(1)}</span>
              <span className="text-[10px] text-muted-foreground">/ 5</span>
            </div>
          </div>
          <div className="flex-1 space-y-1.5">
            {chartData.map((d) => (
              <div key={d.name} className="flex items-center gap-2 text-xs">
                <span className="w-4 font-mono text-muted-foreground">{d.name}</span>
                <div className="h-2 flex-1 overflow-hidden rounded-full bg-muted">
                  <div
                    className="h-full rounded-full"
                    style={{
                      width: `${
                        chartData.reduce((s, x) => s + x.value, 0)
                          ? (d.value / chartData.reduce((s, x) => s + x.value, 0)) * 100
                          : 0
                      }%`,
                      backgroundColor: color,
                    }}
                  />
                </div>
                <span className="w-6 text-right font-mono">{d.value}</span>
              </div>
            ))}
            <div className="flex justify-between pt-1 text-[10px] text-muted-foreground">
              <span>{labels[0]}</span>
              <span>{labels[1]}</span>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

function pct(part: number, total: number) {
  if (!total) return "0%";
  return `${Math.round((part / total) * 100)}%`;
}
